-- Aggiunta reale (#134): 16 specie da orto citate come consociazione da
-- specie del catalogo, ma finora prive di una scheda propria (nessuna
-- pianta reale le referenzia come propria specie). Pagine RHS salvate
-- localmente da Roberta ed elaborate offline.
--
-- Voci generiche verificate su specie/cultivar rappresentative, dichiarate
-- nella fonte di ciascuna riga: cavolo -> Brassica oleracea selvatica
-- (progenitrice di tutte le brassicacee da orto); cipolla -> cultivar
-- 'Red Baron'; fagiolo/pisello/carota -> specie selvatiche progenitrici
-- delle cultivar da orto (pagine RHS dedicate a questo scopo).
--
-- giorni_germinazione/trapianto/raccolta lasciati null per tutte: RHS
-- fornisce solo una categoria "Time to Maturity" (es. "1 year", "2-5
-- years" per i perenni/biennali), non un conteggio preciso di giorni,
-- e non è stata usata nessuna seconda fonte per questo batch.
--
-- Corretta la resistenza al gelo nota discordante per patata (Position
-- RHS riporta "Full shade, Partial shade", ma il testo di Cultivation
-- dice esplicitamente "open, frost-free site": trattata come probabile
-- incoerenza della fonte, non riportata — luce impostata su pieno sole,
-- coerente con la conoscenza agronomica consolidata su questa specie).
--
-- Consociazioni rese simmetriche con il catalogo esistente (#131):
-- aglio/cipolla aggiunte come sfavorevoli a fagiolo/pisello (gli allium
-- sono notoriamente incompatibili con le leguminose, fatto già presente
-- nel catalogo per erba-cipollina/scalogno verso fagiolo/pisello).
--
-- Tossicità reali segnalate, assenti nella prima bozza generata da
-- conoscenza generale: aglio (tossico per animali), fagiolo (baccelli/
-- semi crudi nocivi), patata (parti verdi/germogli tossici tranne il
-- tubero), ruta (fitofotodermatite: tossica per la pelle a contatto con
-- il sole, anche per i cani), asparago (bacche nocive, turioni solo
-- commestibili cotti).

insert into specie
  (nome, nome_scientifico, famiglia_botanica, descrizione, esigenze, alert, manutenzione, ciclo_colturale, vaso, ciclo_vitale, slug, fonti, stato_verifica, verificata_il, verificata_da)
values
($t$Aglio$t$, $t$Allium sativum$t$, $t$Amaryllidaceae$t$, $t$Pianta bulbosa perenne coltivata come annuale: ogni bulbo è formato da più spicchi (bulbilli) usati in cucina. Varietà softneck (bulbi compatti, fioriscono raramente, si conservano bene) o hardneck (spicchi più saporiti, spesso con stelo fiorale, si conservano meno).$t$, $j${"luce": "Pieno sole", "acqua": "Scarsa/moderata", "terreno": "Fertile, ben drenato, alcalino o neutro"}$j$::jsonb, ARRAY[$t$tossico per cani e gatti se ingerito$t$, $t$irritante per la pelle: consigliati i guanti nella manipolazione$t$, $t$piantare in tardo autunno o inizio inverno: il freddo è necessario per una buona bulbificazione$t$, $t$raccogliere quando le foglie ingialliscono$t$, $t$può essere soggetto a minatore fogliare dell'aglio e mosca della cipolla$t$, $t$può essere colpito da marciume bianco, peronospora della cipolla e ruggine del porro$t$], $j${"irrigazione": {"primavera": "ogni 10-14 giorni", "estate": "ogni 7-10 giorni", "autunno": "ogni 14 giorni", "inverno": "nessuna"}, "concimazione": {"primavera": "ogni 30 giorni", "estate": "nessuna", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "5-5-10", "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Amaryllidaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["autunno", "inverno"], "resistenza_gelo": "media", "spaziatura_cm": 15, "consociazioni_favorevoli": ["fragola-rifiorente"], "consociazioni_sfavorevoli": ["fagiolo", "pisello"]}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 3, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.4}$j$::jsonb, $t$annuale$t$, $t$aglio$t$, ARRAY[$t$RHS Plants (rhs.org.uk) — Allium sativum$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (pagine RHS salvate e lette localmente)$t$),
($t$Asparago$t$, $t$Asparagus officinalis$t$, $t$Asparagaceae$t$, $t$Perenne erbacea coltivata per i giovani turioni (germogli) primaverili, commestibili cotti. Il fogliame adulto, piumoso, può raggiungere 1,5m.$t$, $j${"luce": "Pieno sole", "acqua": "Costante, senza ristagni", "terreno": "Fertile, ricco di sostanza organica, sabbioso se possibile"}$j$::jsonb, ARRAY[$t$i germogli (turioni) sono commestibili solo cotti; i frutti (bacche rosse) sono nocivi se ingeriti$t$, $t$indossare guanti nella raccolta: i turioni possono causare irritazione cutanea$t$, $t$propagata per rizomi ("crowns"), non per seme: le piante da seme impiegano più tempo e possono non essere cultivar maschili (più produttive)$t$, $t$evitare le sacche di gelo: i turioni sono delicati al freddo$t$, $t$tagliare il fogliame ingiallito in autunno, a circa 2,5cm dal suolo$t$, $t$può essere soggetto a criocero dell'asparago (asparagus beetle), lumache e lumaconi$t$, $t$può essere colpito da marciume del piede e delle radici, e marciume radicale violetto$t$], $j${"irrigazione": {"primavera": "ogni 7-10 giorni", "estate": "ogni 5-7 giorni", "autunno": "ogni 10-14 giorni", "inverno": "nessuna"}, "concimazione": {"primavera": "ogni 30 giorni", "estate": "ogni 30 giorni", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "taglio del fogliame ingiallito a fine stagione", "inverno": "nessuna"}, "npk": {"primavera": "10-10-10", "estate": "5-10-10", "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Asparagaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "media", "spaziatura_cm": 40, "consociazioni_favorevoli": ["prezzemolo"], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 30, "rinvaso_ogni_mesi": 36, "irrigazione_fattore": 0.7}$j$::jsonb, $t$perenne$t$, $t$asparago$t$, ARRAY[$t$RHS Plants (rhs.org.uk) — Asparagus officinalis$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (pagine RHS salvate e lette localmente)$t$),
($t$Carota$t$, $t$Daucus carota$t$, $t$Apiaceae$t$, $t$Radice a fittone biennale coltivata come annuale. La sottospecie selvatica (Daucus carota) è la progenitrice di tutte le carote coltivate.$t$, $j${"luce": "Pieno sole", "acqua": "Scarsa/moderata", "terreno": "Leggero, profondo, ben drenato, alcalino o neutro"}$j$::jsonb, ARRAY[$t$seminare direttamente in loco: la radice a fittone non tollera bene il trapianto$t$, $t$diradare le piantine appena spuntate, non trapiantarle: gli sfregamenti attirano la mosca della carota$t$, $t$può essere soggetta a mosca della carota e lumache/lumaconi da giovane$t$, $t$generalmente esente da malattie$t$], $j${"irrigazione": {"primavera": "ogni 7-10 giorni", "estate": "ogni 5-7 giorni", "autunno": "ogni 10-14 giorni", "inverno": "nessuna"}, "concimazione": {"primavera": "ogni 30 giorni", "estate": "ogni 30 giorni", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "5-10-10", "estate": "5-10-10", "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Apiaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": ["primavera", "estate"], "finestra_trapianto": [], "resistenza_gelo": "alta", "spaziatura_cm": 8, "consociazioni_favorevoli": ["erba-cipollina", "peperoncino", "pomodoro", "scalogno"], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 10, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.4}$j$::jsonb, $t$annuale$t$, $t$carota$t$, ARRAY[$t$RHS Plants (rhs.org.uk) — Daucus carota (specie selvatica, progenitrice delle cultivar da orto)$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (pagine RHS salvate e lette localmente)$t$),
($t$Cavolo$t$, $t$Brassica oleracea$t$, $t$Brassicaceae$t$, $t$Voce generica del catalogo: verificata sulla pagina RHS della specie selvatica Brassica oleracea, progenitrice di tutte le brassicacee da orto (cavolo cappuccio, cavolfiore, verza, cavolo nero, ecc.). Per una cultivar specifica i dati possono variare, in particolare dimensioni e spaziatura.$t$, $j${"luce": "Pieno sole o mezz'ombra", "acqua": "Regolare", "terreno": "Fertile, compatto, non troppo acido, alcalino o neutro"}$j$::jsonb, ARRAY[$t$voce generica: le dimensioni e la spaziatura variano molto a seconda del tipo di cavolo coltivato$t$, $t$attira le farfalle cavolaie, i cui bruchi possono danneggiare le foglie$t$, $t$molto appetito da piccioni e lumache$t$, $t$l'altica (flea beetle) può danneggiare le piantine giovani$t$, $t$può essere colpito da peronospora e ruggine bianca delle brassicacee$t$], $j${"irrigazione": {"primavera": "ogni 5-7 giorni", "estate": "ogni 3-5 giorni", "autunno": "ogni 7 giorni", "inverno": "nessuna"}, "concimazione": {"primavera": "ogni 21 giorni", "estate": "ogni 21 giorni", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "10-10-10", "estate": "10-10-10", "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Brassicaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": ["primavera"], "finestra_trapianto": ["primavera", "estate"], "resistenza_gelo": "alta", "spaziatura_cm": null, "consociazioni_favorevoli": ["rosmarino", "timo-serpillo", "salvia", "lavanda", "calendula"], "consociazioni_sfavorevoli": ["fragola-rifiorente", "pomodoro"]}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 20, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.7}$j$::jsonb, $t$perenne$t$, $t$cavolo$t$, ARRAY[$t$RHS Plants (rhs.org.uk) — Brassica oleracea (voce generica del catalogo, specie selvatica 